package binarydist

import (
	"bytes"
	"crypto/rand"
	"testing"
)

func TestQsufsort(t *testing.T) {
	// Load the checked-in fixture only when this test runs. Package initialization
	// must not depend on files generated by earlier test runs.
	sortT := [][]byte{
		mustRandBytes(1000),
		readFixture(t, "sample.old"),
		[]byte("abcdefabcdef"),
	}
	for _, s := range sortT {
		I := qsufsort(s)
		for i := 1; i < len(I); i++ {
			if bytes.Compare(s[I[i-1]:], s[I[i]:]) > 0 {
				t.Fatalf("unsorted at %d", i)
			}
		}
	}
}

func mustRandBytes(n int) []byte {
	b := make([]byte, n)
	_, err := rand.Read(b)
	if err != nil {
		panic(err)
	}
	return b
}
